<?php
namespace App\Jobs;
use App\Jobs\Concerns\HasTenantContext; use App\Models\{ReportExport}; use App\Services\AccountingService; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Bus\Queueable; use Illuminate\Support\Facades\Storage;
final class GenerateReportExport implements ShouldQueue { use Queueable,HasTenantContext; public function __construct(string $tenantId,public readonly string $exportId){$this->tenantId=$tenantId;} public function handle(AccountingService $accounting):void{$export=ReportExport::where('tenant_id',$this->tenantId)->findOrFail($this->exportId);try{$filters=$export->filters??[];$rows=$export->report_key==='trial_balance'?$accounting->trialBalance($this->tenantId,$filters['company_id'],$filters['from'],$filters['to']):[];$csv='Account,Type,Debit,Credit,Balance\n';foreach($rows as $row)$csv.=implode(',',array_map(fn($v)=>'"'.str_replace('"','""',(string)$v).'"',[$row['account'],$row['account_type'],$row['debit'],$row['credit'],$row['balance']]))."\n";$path='private/reports/'.$export->id.'.csv';Storage::disk('local')->put($path,$csv);$export->update(['state'=>'completed','private_path'=>$path,'completed_at'=>now()]);}catch(\Throwable $e){$export->update(['state'=>'failed','error'=>$e->getMessage()]);throw $e;}} }
